<script lang="ts">export let username:string;export let password:string;export let onClose:()=>void;let copied=false;async function copy(){try{await navigator.clipboard.writeText(password);copied=true;}catch{copied=false;}}</script>
<div class="card stack" role="status"><div class="row between wrap"><h3>User credentials created</h3><button class="btn secondary small" type="button" on:click={onClose}>Dismiss</button></div><p class="subtitle">Sample credentials · not connected to an actual database.</p><div class="summary-list"><div><span>Username</span><strong>{username}</strong></div></div><label class="field">One-time sample password<div class="row wrap"><input class="input grow" readonly value={password}/><button class="btn secondary" type="button" on:click={copy}>{copied?'Copied':'Copy'}</button></div></label><small>Sample password is not stored in browser data; it cannot authenticate anywhere.</small></div>
